insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (2, 'Evie and Rhino', 'McMullin, Neridah', NULL, 'A young girl with a tragic past and a rhinoceros facing life in captivity form an unlikely and magical bond after a fateful storm and a shipwreck bring them together. On a stormy night off the coast of southern Australia in 1891, a ship transporting a cargo of exotic animals tosses and turns in enormous seas, and a young rhino cries out in fear. A few miles inland, ten-year-old Evie and her grandfather shelter in their crumbling, once-grand old home. After the devastating storm that killed Evie''s parents and the resulting grief that left Evie mute, they know too well how deadly storms can be. When all is calm, Evie treks down to the water and makes an extraordinary discovery—a discovery that will change her life, and Rhino''s, forever. Evie and Rhino is an engaging and moving tale about love, connection, and the healing power of friendship.', 'verified', '002_evie_and_rhino.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (3, 'Wombat Stew', 'Vaughan, Marcia', 'Pamela Lofts', 'A dingo intent on making wombat stew receives cooking suggestions from the other animals, unaware that they are protecting their fellow creature.', 'verified', '003_wombat_stew.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (4, 'Tuesday', 'Wiesner, David', NULL, 'Frogs rise on their lily pads, float through the air, and explore the nearby houses while their inhabitants sleep.', 'verified', '004_tuesday.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (5, 'On a Magical Do-Nothing Day', 'Alemagna, Beatrice', 'Beatrice Alemagna', 'The game drives my mum mad. She takes it away. I take it back. I wish Dad had come with us on this rainy, grey weekend. Without my game, nothing is fun. On the other hand, maybe I''m wrong about that...', 'verified', '005_on_a_magical_donothing_day.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (6, 'Who Sank the Boat?', 'Allen, Pamela', NULL, 'Who sank the boat? Was it the cow or the donkey or the sheep with her knitting? Surely it wasn’t the tiny little mouse? Winner of the 1983 Australian Picture Book of the Year Award, this wonderfully illustrated book is designed for sharing aloud and will make children giggle as they guess which animal spoilt a day’s rowing by sinking the boat.', 'verified', '006_who_sank_the_boat.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (7, 'Frank''s Red Hat', 'Avery, Sean', 'Sean E Avery', 'A story about never giving up on your talents, because even though what you do may not be appreciated right now, it may be in time. Possibly by someone you''d least expect. Frank is a penguin with ideas. Mostly terrible ones. That''s why his fellow penguins are nervous when he shows them his strange new creation. Something they''d never seen or expected to see in their cold and colourless Antarctic world - a red hat.', 'verified', '007_franks_red_hat.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (8, 'Boo Loves Books', 'Baillie, Kaye', 'Tracie Grimwood', 'Everyone else in class loves reading, but Phoebe hates it. It makes her feel anxious and she worries about getting words wrong. She is even more anxious when she finds out that she and her classmates will be taking a trip to an animal shelter to read to...the dogs! But when Phoebe meets Big Boo, a nervous but gentle dog, maybe they can face their fears together?', 'verified', '008_boo_loves_books.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (9, 'When the Waterhole Dries Up', 'Baillie, Kaye', NULL, 'It''s bath time in the outback, and a dusty boy is waiting, but so are some very dusty and very cheeky animals. Will this boy ever get clean? A rollicking tale about togetherness and fun!', 'verified', '009_when_the_waterhole_dries_up.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (10, 'The Story of Rosy Dock', 'Baker, Jeannie', 'Jeannie Baker', 'The Australian desert: for thousands of years the only changes here were made by the wind, the willy-willies and sometimes the rain. Then a hundred years ago people from Europe settled in the desert and planted seeds from the other side of the world. The Story of Rosy Dock is the story of one of the settlers who followed them, and her garden in the wilderness, a garden that is beautiful - but with an unexpected flowering.', 'verified', '010_the_story_of_rosy_dock.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (11, 'Scar Town', 'Bancks, Tristan', NULL, 'A missing father. A drowned town. A buried secret. Three friends on a dangerous mission to uncover the truth.

Seven years after Old Scarborough was drowned, a house is emerging from the water. Will and his friends Dar and Juno dare each other to explore it.

But when they find bones – and a stash of cash – they realise they''re not the only ones interested in its secrets.

Now they''re fighting for their lives against the men who want what they found. Will can''t leave the mystery alone, though. What if the bones belong to his missing dad?', 'verified', '011_scar_town.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (12, 'Edie''s Experiments: How to Make Friends', 'Barkla, Charlotte', 'Sandy Flett', 'I’m Edie and I love science. So when I started at a new school, I decided it could be one giant experiment. Can I give you some advice? Avoid sliming your entire classroom. You could end up in trouble with your teacher, your new classmates and the principal. Between the great slime fiasco, the apology cookie surprise and the wrinkle cream mix-up, I’ve discovered making friends isn’t an exact science!', 'verified', '012_edies_experiments_how_to_make_friends.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (13, 'Edie''s Experiments: How to be the Best', 'Barkla, Charlotte', 'Sandy Flett', 'I''m Edie and I''m obsessed with science. So I was sure that Annie B and I would win the Eco Fair competition. Then Dean Starlight arrived and started sabotaging our project. Now the competition has become an epic science battle of robotic spider attacks, exploding foam and sneaky spying. Dean thinks he''s the best scientist of Class 5Z, but we''ll show him ...', 'verified', '013_edies_experiments_how_to_be_the_best.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (14, 'All Bodies Are Good Bodies', 'Barkla, Charlotte', NULL, 'A colorful and rhyming celebration of every kind of body.', 'verified', '014_all_bodies_are_good_bodies.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (15, 'From my Head to my Toes, I Say What Goes', 'Barkla, Charlotte', NULL, 'A light-hearted exploration of boundaries, this book discusses consent and control for a young audience. As with All Bodies Are Good Bodies, this story is bold and beautiful, loud and proud, with the feel-good factor turned up to eleven.', 'verified', '015_from_my_head_to_my_toes_i_say_what_goes.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (16, '11 Ruby Road 1900', 'Barkla, Charlotte', NULL, 'Perfect period fiction for middle-grade girls - for fans of the Our Australian Girl series It is 1900 and Dorothy and her family have just moved to a new house at 11 Ruby Road. Ruby Road is a busy street, bustling with activity - families and children, noisy carts and animals. The house is close enough to see the city and very different from the rural life Dorothy has known. Best of all it has a secret writing room that only she knows about! Dorothy has big plans for her new neighbourhood - she wants to put on a play and write it herself! But there are other reasons for her family''s move to the city and, as Dorothy starts to learn about her new house, she discovers more about the period of time she''s growing up in.', 'verified', '016_11_ruby_road_1900.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (17, 'What Do You Call Your Grandma?', 'Barton, Ashleigh', NULL, 'An inclusive picture book for grandparents everywhere. In every country around the world are grandmas short and tall. Though they go by different names, we love them one and all. What Do You Call Your Grandma? is a love letter to grandmothers and families from every corner of the globe.', 'verified', '017_what_do_you_call_your_grandma.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (18, 'The Eleventh Hour', 'Base, Graeme', NULL, 'An elephant''s eleventh birthday party is marked by eleven games preceding the banquet to be eaten at the eleventh hour; but when the time to eat arrives, the birthday feast has disappeared. The reader is invited to guess the thief.', 'verified', '018_the_eleventh_hour.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (19, 'Animalia', 'Base, Graeme', NULL, 'Within the pages of this book You may discover, if you look Beyond the spell of written words, A hidden land of beasts and birds. For many things are ''of a kind,'' And those with keenest eyes will find A thousand things, or maybe more - It''s up to you to keep the score . . . Visit graemebase.com Visit Animalia on Facebook', 'verified', '019_animalia.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (20, 'Everybody Needs a Rock', 'Baylor, Byrd', NULL, 'Everybody needs a rock -- at least that''s the way this particular rock hound feels about it in presenting her own highly individualistic rules for finding just the right rock for you.', 'verified', '020_everybody_needs_a_rock.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (21, 'All of the Factors of Why I Love Tractors', 'Bell, Davina', NULL, 'When Frankie McGee visits the library, he has his sights set on borrowing a book about tractors—again! Why? Let him tell you! This laugh-out-loud picture book from award-winning author Davina Bell and illustrator Jenny Løvlie is a great choice for anyone who loves vehicles, transportation, things that go, and reading.', 'verified', '021_all_of_the_factors_of_why_i_love_tractors.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (22, 'The Patchwork Bike', 'Beneba Clarke, Maxine', 'Van T Rudd', 'It has a bent bucket seat, bashed tin-can handlebars, and wood-cut wheels — and riding the patchwork bike that you and your crazy brothers made is the best fun in the whole village.

When you live in a village at the edge of the no-go desert, you need to make your own fun. That''s when you and your brothers get inventive and build a bike from scratch, using everyday items like an old milk pot (maybe Mum is still using it, maybe not) and a used flour sack. You can even make a license plate from bark if you want. The end result is a spectacular bike, perfect for whooping and laughing as you bumpetty bump over sand hills, past your fed-up mum and right through your mud-for-walls home. A joyous story by multi-award-winning author Maxine Beneba Clarke, beautifully illustrated by street artist Van Thanh Rudd.', 'verified', '022_the_patchwork_bike.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (23, 'Just One Bee', 'Bertini, Anthony & Lamond, Margrete', NULL, 'All it takes is the will to make dreams come true. Just One Bee is a story of hope, determination and never giving up: the story of One-bee and her dream to revert desolate wastes back to fields of flowers. But to change a desert to meadowland she needs to go it alone because when she comes across another bee, she discovers not only is he hoarding a single precious flower and a queen bee, but he refuses to believe positive change is possible. Other-bee does all he can to quash One-bee''s dream. But One-bee''s persistence, patience and optimism eventually prove Other-bee wrong, and she shows him how dreams can come true.', 'verified', '023_just_one_bee.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (24, 'Pearl Barley and Charlie Parsley', 'Blabey, Aaron', 'Aaron Blabey', 'Pearl and Charlie are best friends, although they seem to be different in every way.', 'verified', '024_pearl_barley_and_charlie_parsley.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (25, 'If I Was a Horse', 'Blackall, Sophie', NULL, 'I could go anywhere I want . . . If you were a horse, what would you do? Could you fit in your clothes? Would you give your little sister a ride? Would your brother even notice? Gallop along with two-time Caldecott Medallist Sophie Blackall through this riotous day in the life of a child who imagines their life as a horse. Sophie''s delightful text and resonant illustrations that feature a giant horse in familiar settings offer a visual feast, a grand dose of joy and a celebration of the real power of imagination to help us navigate the world. ''This is truly a book that will be treasured by any child who loves horses . . . Absolutely gorgeous and brilliant fun for ages 2+'' READINGS', 'verified', '025_if_i_was_a_horse.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (26, 'Farmhouse', 'Blackall, Sophie', NULL, 'Based on a real family and an actual farmhouse where Sophie salvaged facts and artefacts for the making of this spectacular work, page after page bursts with luminous detail and joy. Join the award-winning, bestselling Sophie Blackall as she takes readers on an enchanting visit to a farmhouse across time, to witness the way that history spins stories. ''Hums with life and the joys and tribulations of a large family ... The story itself is told in lilting text which reads so well aloud, and the accompanying illustrations are colourful and joyous. I loved this book without reservation'' Readings PRAISE FOR SOPHIE BLACKALL: ''Painted with the featherlight touch that distinguishes Caldecott Medallist Blackall''s work, this graceful account of a lighthouse keeper''s life celebrates a lost era ... A jewel of a creation and a gift to those who dream of retreat'' PUBLISHERS WEEKLY', 'verified', '026_farmhouse.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (27, 'The Boy and the Elephant', 'Blackwood, Freya', NULL, 'From an award-winning illustrator comes a tender, magical, and gorgeously rendered wordless picture book about a boy who saves the trees in the lot next door from being cut down. Amongst the hustle and bustle of the city is an overgrown piece of land where trees and wildlife thrive. A boy, who lives in a house on the lot next to it, loves to visit. He has a friend there: an elephant, an animal that he sees within the shapes of the trees. No matter the weather, the boy visits. And as the seasons change so does the elephant; thick green foliage changes to autumnal colors before the bare branches of harsh winter appear. But one day, builders arrive. The land has been sold, and the trees have been marked for removal. The boy can''t lose his elephant, and so he comes up with a plan. Unbearably beautiful and moving, and with a touch of magical realism, here is a wordless picture book about conservation and children''s ability to be powerful agents of change.', 'verified', '027_the_boy_and_the_elephant.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (28, 'The Great Rabbit Chase', 'Blackwood, Freya', 'Freya Blackwood', 'Gumboots is a beautiful pet rabbit, but he likes to escape. A story that celebrates what it means to live in a community and a reminder that life is full of surprises.', 'verified', '028_the_great_rabbit_chase.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (29, 'The Unwilling Twin', 'Blackwood, Freya', 'Freya Blackwood', 'A gorgeous picture book from seven-time CBCA Book of the Year winner Freya Blackwood. Shortlisted in the 2021 CBCA Book of the Year Awards. Jules and George are the same in every way. It is quite impossible to tell them apart. Like all twins, Jules and George do everything together. But after a long, hot day at the beach, even twins sometimes disagree ... From multi-award-winning picture book creator Freya Blackwood comes a cheeky and charming story about the ups and downs of sibling love. AWARDS Shortlisted - CBCA Book of the Year Award (Picture Book) 2021', 'verified', '029_the_unwilling_twin.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (30, 'Walk of the Whales', 'Bland, Nick', NULL, 'When all of the whales in the ocean leave their home to walk around on land, people don''t quite know what to think. But soon shopkeepers go out of business, farms are flooded with water and salt, and people shout horrible, anti-whale words. That is, until, a smart little girl decides to ask the whales what everyone can do to help. A powerful and entertaining story about the environment from best-selling author, Nick Bland.', 'verified', '030_walk_of_the_whales.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (31, 'The Enchanted Wood', 'Blyton, Enid', NULL, 'Enid Blyton''s "The Enchanted Wood" invites readers into a whimsical realm, brilliantly blending elements of fantasy and adventure through its captivating narrative style. Set against the backdrop of an imagined wood populated by fantastical creatures, Blyton masterfully employs vivid descriptions and child-friendly prose, making it engaging for young readers. The book serves not only as a captivating tale but also as a reflection of the early 20th-century British literary context, where the exploration of nature and the imagination was paramount amidst a rapidly industrializing society. Enid Blyton, a prolific British author, is celebrated for her children''s literature that often champions themes of friendship, courage, and the joys of childhood. Drawing on her own childhood memories of exploration and adventure, Blyton created "The Enchanted Wood" as part of her broader oeuvre aimed at sparking imagination and curiosity within her young audience. Her understanding of children''s experiences and emotions is evident throughout the narrative, making her books timeless treasures for generations of readers. This enchanting tale is highly recommended for children and parents alike, as it beautifully encapsulates the allure of whimsy and imagination. It encourages readers to embrace adventure and appreciate the magic that resides in nature, making it a perfect bedtime story or a delightful read-aloud for family bonding.', 'verified', '031_the_enchanted_wood.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (32, 'Australia from dawn to dusk', 'Brentos', NULL, 'A photographic journey through Australia showcasing the continent''s diverse landscapes, wildlife and natural beauty from sunrise to sunset. Stunning images capture the unique Australian environment across different regions and times of day.', 'needs_review', '032_australia_from_dawn_to_dusk.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (33, 'Fireflies!', 'Brinckloe, Julie', NULL, 'Fireflies is Julie Brinckloe''s "reflects a classic theme in children''s literature—the need to set something free in order to keep it." (The Horn Book) A young boy is proud of having caught a jar full of fireflies, which seems to him like owning a piece of moonlight, but as the light begins to dim he realizes he must set the insects free or they will die.', 'verified', '033_fireflies.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (34, 'The Important Book', 'Brown, Margaret Wise', NULL, 'a book that points out the important things about everyday objects and what makes them special. A word game for young children.', 'verified', '034_the_important_book.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (35, 'Six Dots: A Story of Young Louis Braille', 'Bryant, Jen', 'Boris Kulikov', 'An inspiring picture-book biography of Louis Braille—a blind boy so determined to read that he invented his own alphabet. **Winner of a Schneider Family Book Award!** Louis Braille was just five years old when he lost his sight. He was a clever boy, determined to live like everyone else, and what he wanted more than anything was to be able to read. Even at the school for the blind in Paris, there were no books for him. And so he invented his own alphabet—a whole new system for writing that could be read by touch. A system so ingenious that it is still used by the blind community today. Award-winning writer Jen Bryant tells Braille’s inspiring story with a lively and accessible text, filled with the sounds, the smells, and the touch of Louis’s world. Boris Kulikov’s inspired paintings help readers to understand what Louis lost, and what he was determined to gain back through books. An author’s note and additional resources at the end of the book complement the simple story and offer more information for parents and teachers. Praise for Six Dots: "An inspiring look at a child inventor whose drive and intelligence changed to world—for the blind and sighted alike."—Kirkus Reviews "Even in a crowded field, Bryant’s tightly focused work, cast in the fictionalized voice of Braille himself, is particularly distinguished."—Bulletin, starred review "This picture book biography strikes a perfect balance between the seriousness of Braille’s life and the exuberance he projected out into the world." — School Library Journal, starred review', 'verified', '035_six_dots_a_story_of_young_louis_braille.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (36, 'Smoky Night', 'Bunting, Eve', NULL, 'In a night of rioting, Daniel and his mother are forced to leave their apartment for the safety of a shelter. "Diaz has not been afraid to take risks in illustrating the story with thickly textured paintings against a background of torn-paper and found-object collage. Without becoming cluttered or gimmicky, these pictures manage to capture a calamitous atmosphere that finally calms. . . . Both author and artist have managed to portray a politically charged event without pretense or preaching."--The Bulletin', 'verified', '036_smoky_night.jpg');
